// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Call withdrawAll with a recipient different from msg.sender
        address recipient = address(0x123);
        vm.prank(address(this)); // msg.sender is deployer/owner (address(this))
        c.withdrawAll(recipient);
        // Assert: reference sends all balance to recipient, so contract balance becomes 0
        // Bug sends to msg.sender (deployer), so contract balance remains 1 ether
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with some ether so balance is non-zero
        vm.deal(address(c), 1 ether);
        // Call withdrawAll from a non-owner account (address(1))
        vm.prank(address(1));
        bool ok;
        try c.withdrawAll(address(1)) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference C requires msg.sender == owner (which is address(this)), so it reverts -> ok false.
        // The buggy M has no require, so it succeeds -> ok true.
        // Assert that the reference holds (ok == false), which the buggy version breaks (ok == true).
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(address(c), 1 ether);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll(nonOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

