pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        address recipient = address(0x1234);
        // Owner calls withdrawAll
        c.withdrawAll(recipient);
        // Reference succeeds: contract balance becomes 0
        assertTrue(address(c).balance == 0);
    }
}
